<?php use yii\helpers\{Html,Url};$this->title='Jadwal Perkuliahan';?>
<div class="d-flex justify-content-between mb-3"><div><h1 class="mb-0">Jadwal Perkuliahan</h1><span class="text-muted">Jadwal dan Riwayat Perkuliahan Kelas</span></div><div><?=Html::a('Kembali ke Daftar',['index'],['class'=>'btn btn-primary'])?> <?=Html::a('<i class="fas fa-plus"></i> Tambah Data',['meeting-create','id'=>$model->id],['class'=>'btn btn-success'])?> <?=Html::button('<i class="far fa-calendar-alt"></i> Buat Perencanaan',['class'=>'btn btn-warning','id'=>'plan-meetings'])?></div></div><div class="card card-success card-outline"><div class="card-body"><div class="row"><div class="col-md-2"><?=$this->render('_detail_nav',['model'=>$model,'active'=>'meetings'])?></div><div class="col-md-10"><?=$this->render('_class_summary',['model'=>$model])?><div class="table-responsive"><table class="table table-bordered table-striped"><thead class="thead-dark"><tr><th>Pert.</th><th>Hari</th><th>Waktu</th><th>Ruang</th><th>Realisasi</th><th>Pengajar</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($meetings as $meeting):?><tr><td><?=$meeting->meeting_number?></td><td><?=Yii::$app->formatter->asDate($meeting->schedule_date,'php:l, d-m-Y')?></td><td><?=substr($meeting->startTimeSlot->time,0,5).' - '.substr($meeting->endTimeSlot->time,0,5)?></td><td><?=Html::encode($meeting->lectureRoom->name??$meeting->location??'-')?></td><td><?=Html::encode($meeting->realized_material?:'-')?></td><td><?=Html::encode($meeting->lecturer->employee->user->name??'-')?></td><td><?=Html::encode($meeting::statusOptions()[$meeting->status])?></td><td><?=Html::a('<i class="fas fa-edit"></i>',['meeting-update','id'=>$model->id,'meeting_id'=>$meeting->id],['class'=>'btn btn-primary btn-sm'])?> <?=Html::button('<i class="fas fa-trash"></i>',['class'=>'btn btn-danger btn-sm js-delete-meeting','data-url'=>Url::to(['meeting-delete','id'=>$model->id,'meeting_id'=>$meeting->id])])?></td></tr><?php endforeach?><?php if(!$meetings):?><tr><td colspan="8" class="text-center text-muted">Data kosong</td></tr><?php endif?></tbody></table></div></div></div></div></div>
<?php $plan=Url::to(['plan-meetings','id'=>$model->id]);$csrf=Yii::$app->request->csrfToken;$js=<<<JS
$('#plan-meetings').on('click',function(){Swal.fire({title:'Buat perencanaan jadwal?',text:'Jadwal mingguan akan dibuat sampai jumlah pertemuan kelas.',icon:'question',showCancelButton:true,confirmButtonText:'Ya, buat',cancelButtonText:'Batal'}).then(function(r){if(!r.isConfirmed)return;$.post('$plan',{_csrf:'$csrf'}).done(function(x){Swal.fire(x.success?'Berhasil':'Gagal',x.message,x.success?'success':'error').then(function(){if(x.success)location.reload();});});});});$('.js-delete-meeting').on('click',function(){var u=$(this).data('url');Swal.fire({title:'Hapus jadwal?',icon:'warning',showCancelButton:true,confirmButtonText:'Ya, hapus',cancelButtonText:'Batal'}).then(function(r){if(!r.isConfirmed)return;$.post(u,{_csrf:'$csrf'}).done(function(x){Swal.fire('Berhasil',x.message,'success').then(function(){location.reload();});});});});
JS;$this->registerJs($js);?>
